abstract class Shape {
    abstract double area(); // le message commun
}

class Circle extends Shape {
    private final double r;
    Circle(double r) { this.r = r; }
    double area() { return Math.PI * r * r; }
}

class Square extends Shape {
    private final double side;
    Square(double side) { this.side = side; }
    double area() { return side * side; }
}

// L'appelant ignore le type réel : il parle à l'abstraction
double totalArea(List<Shape> shapes) {
    return shapes.stream().mapToDouble(Shape::area).sum();
}

// Polymorphisme paramétrique : un seul code, tout type, type-safe
interface Repository<T> {
    void save(T entity);
    Optional<T> findById(UUID id);
}

// Polymorphisme de sous-typage : le type réel décide du comportement
interface PricingPolicy { Money price(Order o); }
class StandardPricing implements PricingPolicy { public Money price(Order o) { /* ... */ return Money.of(10); } }
class VipPricing implements PricingPolicy { public Money price(Order o) { /* ... */ return Money.of(7); } }
// Le code appelant dépend de l'abstraction, pas du type concret (Open/Closed)

// ❌ Anémique : Order n'est qu'une structure ; la règle vit dehors, invariants non protégés
class Order { private Status status; public void setStatus(Status s){ this.status = s; } /* + getters/setters */ }
class OrderService {
    void ship(Order o) {
        if (o.getStatus() != Status.PAID) throw new IllegalStateException();
        o.setStatus(Status.SHIPPED);   // n'importe qui peut aussi faire setStatus(SHIPPED) sans payer
    }
}

// ✅ Riche : Order porte sa règle, l'état invalide est irreprésentable (Tell, Don't Ask + Information Expert)
class Order {
    private Status status;
    public void ship() {
        if (status != Status.PAID)
            throw new DomainException("une commande non payée ne peut pas être expédiée");
        this.status = Status.SHIPPED;
    }
    public Status status() { return status; }   // lecture, pas de setter public
}
